CREATE TEMP TABLE demo_new_courses(id uuid PRIMARY KEY) ON COMMIT DROP;

WITH added AS (INSERT INTO course (id,creator_id,title,description,country_id,difficulty_id,estimated_minutes,price_coins,reward_coins,visibility_id,created_at,archived_at) VALUES
  ('efdd2a13-b3a7-94bf-7dc8-e7cf1ce35da1','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06','Bull riding & the corrida tradition','The corrida grew from Andalusian horsemanship into a ritual with set stages: picadors, banderillas and a final faena. Compare the 1785 ring at Ronda with Seville Maestranza and Las Ventas in Madrid, which opened in 1931.',(SELECT id FROM country WHERE iso_code='ES'),(SELECT id FROM difficulty WHERE label='INTERMEDIATE'),90,70,10,(SELECT id FROM visibility WHERE label='PUBLIC'),now()-interval '1416 hours',NULL),
  ('9870388e-825d-f5f2-0931-6e02d194c186','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06','Doñana wetlands & the Iberian lynx','Doñana marshes, dunes and pine forests shelter the Iberian lynx, one of the most endangered wild cats on Earth. Learn how seasonal floods drive bird migrations and why water management shapes the wetlands.',(SELECT id FROM country WHERE iso_code='ES'),(SELECT id FROM difficulty WHERE label='INTERMEDIATE'),75,0,10,(SELECT id FROM visibility WHERE label='PUBLIC'),now()-interval '1415 hours',NULL),
  ('350bab1d-9928-ea03-26a3-c836689e00e4','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06','Alhambra and Moorish geometry','The Alhambra is covered in geometric tilework of stars and polygons, cut and fitted by hand. Compare it with the Mezquita in Cordoba and the Real Alcazar in Seville, built by Moorish and Christian hands.',(SELECT id FROM country WHERE iso_code='ES'),(SELECT id FROM difficulty WHERE label='INTERMEDIATE'),120,100,10,(SELECT id FROM visibility WHERE label='PUBLIC'),now()-interval '1414 hours',NULL),
  ('97fa4b7c-8b34-d488-fd77-d7468402a740','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06','Flamenco rhythm & Andalusian guitar','Flamenco mixes song, guitar and handclapping in palos, each with its own rhythmic cycle called compas. Learn the patterns of alegrias and bulerias, then trace how Triana in Seville shaped the style.',(SELECT id FROM country WHERE iso_code='ES'),(SELECT id FROM difficulty WHERE label='BEGINNER'),60,50,10,(SELECT id FROM visibility WHERE label='PUBLIC'),now()-interval '1413 hours',NULL),
  ('ac3da173-5818-0f05-1b5e-f6e0aadd1693','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06','Jamón ibérico & acorn-fed pigs','Iberian pigs that forage on acorns in oak dehesas produce jamón ibérico de bellota, cured for years. Learn how breed, diet and curing time set the grades and why the fat softens at low temperatures.',(SELECT id FROM country WHERE iso_code='ES'),(SELECT id FROM difficulty WHERE label='BEGINNER'),45,40,10,(SELECT id FROM visibility WHERE label='PUBLIC'),now()-interval '1412 hours',NULL),
  ('94e81c58-923a-fe34-9cae-40da0458dd4a','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06','Palio di Siena: the horse race','Twice a year, ten of the seventeen contrade race bareback horses around the Piazza del Campo. Learn how contrade loyalty and the blessing of horses turn one race into a year-long city event.',(SELECT id FROM country WHERE iso_code='IT'),(SELECT id FROM difficulty WHERE label='BEGINNER'),60,50,10,(SELECT id FROM visibility WHERE label='PUBLIC'),now()-interval '1411 hours',NULL),
  ('737dc601-c0db-a742-6fcb-669e81804ced','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06','Roman concrete and the Pantheon','Roman builders mixed volcanic ash with lime to make concrete that still holds the Pantheon dome. Compare the Pantheon with Pompeii, where Roman walls and mortar were preserved under ash after the eruption of 79 AD.',(SELECT id FROM country WHERE iso_code='IT'),(SELECT id FROM difficulty WHERE label='ADVANCED'),150,120,10,(SELECT id FROM visibility WHERE label='PUBLIC'),now()-interval '1410 hours',NULL),
  ('7babf7a6-8cb1-f669-ea13-3da800aba052','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06','Mount Etna volcanic ecosystems','Mount Etna is one of the most active volcanoes on Earth, and new lava fields are colonized by pioneer plants. Study how ash soils, altitude zones and frequent eruptions shape this rare ecosystem.',(SELECT id FROM country WHERE iso_code='IT'),(SELECT id FROM difficulty WHERE label='INTERMEDIATE'),90,70,10,(SELECT id FROM visibility WHERE label='PUBLIC'),now()-interval '1409 hours',NULL),
  ('bb355a7c-2359-e5ba-380f-04245216d600','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06','Parmigiano-Reggiano and dairy craft','Parmigiano-Reggiano is made only in a defined area of northern Italy from cow milk, salt and rennet, with no additives. Learn why wheels age for at least twelve months and how graders judge them by tapping.',(SELECT id FROM country WHERE iso_code='IT'),(SELECT id FROM difficulty WHERE label='BEGINNER'),40,40,10,(SELECT id FROM visibility WHERE label='PUBLIC'),now()-interval '1408 hours',NULL),
  ('4af06a45-e646-448a-3066-9617c56b2a1d','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06','Olympia and the ancient Games','The Olympic Games began at Olympia in 776 BC according to tradition, with a single footrace as the first event. Trace how the Pythian and Panathenaic festivals spread athletic contests across the Greek world.',(SELECT id FROM country WHERE iso_code='GR'),(SELECT id FROM difficulty WHERE label='BEGINNER'),60,50,10,(SELECT id FROM visibility WHERE label='PUBLIC'),now()-interval '1407 hours',NULL),
  ('499067d6-d442-856c-c629-ac98d2059602','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06','Delphi, the oracle and city-states','The oracle of Apollo at Delphi was consulted by city-states and rulers across the Mediterranean for centuries. Read the treasury inscriptions, then compare its politics with the Acropolis of Athens.',(SELECT id FROM country WHERE iso_code='GR'),(SELECT id FROM difficulty WHERE label='INTERMEDIATE'),105,80,10,(SELECT id FROM visibility WHERE label='PUBLIC'),now()-interval '1406 hours',NULL),
  ('12b0a2d2-4a3a-371d-74ab-6038c42ee3c3','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06','Loggerhead turtles of Zakynthos','Loggerhead sea turtles nest on Zakynthos beaches and often return to the shores where they hatched. Learn how nest protection, beach lighting and boat traffic affect how many hatchlings reach the sea.',(SELECT id FROM country WHERE iso_code='GR'),(SELECT id FROM difficulty WHERE label='BEGINNER'),75,60,10,(SELECT id FROM visibility WHERE label='PUBLIC'),now()-interval '1405 hours',NULL),
  ('5b2daa65-e4ca-7c84-1de1-0d0e949d5b80','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06','Petanque and Provence village games','Petanque was developed in La Ciotat in 1907, when a player with rheumatism invented a standing-still throw. Learn the rules of boules, how the cochonnet is placed and why the game suits village squares.',(SELECT id FROM country WHERE iso_code='FR'),(SELECT id FROM difficulty WHERE label='BEGINNER'),30,40,10,(SELECT id FROM visibility WHERE label='PUBLIC'),now()-interval '1404 hours',NULL),
  ('7b5bb64d-485d-59ed-e150-85b738ec22b2','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06','Monet gardens at Giverny','Claude Monet reworked his Giverny garden into a painting subject, with a water garden and a Japanese footbridge. Compare his water lily series with how light and colour change across a single summer.',(SELECT id FROM country WHERE iso_code='FR'),(SELECT id FROM difficulty WHERE label='BEGINNER'),75,60,10,(SELECT id FROM visibility WHERE label='PUBLIC'),now()-interval '1403 hours',NULL),
  ('dd0f3cf9-e34d-c42c-d8d7-7342a809b740','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06','Camargue flamingos and salt marshes','The Camargue delta hosts large numbers of greater flamingos, which feed in shallow lagoons and salt pans. Learn how river sediment, tides and salinity create bird habitats and why grazing bulls shape the land.',(SELECT id FROM country WHERE iso_code='FR'),(SELECT id FROM difficulty WHERE label='INTERMEDIATE'),90,70,10,(SELECT id FROM visibility WHERE label='PUBLIC'),now()-interval '1402 hours',NULL),
  ('51f6cc88-c8ea-91c9-65ed-18e5e1c65a0b','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06','Champagne and the Marne valley','Champagne is sparkling wine made only in its namesake region of France, fermented a second time in the bottle. Learn the traditional method, from blending base wines to riddling, and why chalk soils matter.',(SELECT id FROM country WHERE iso_code='FR'),(SELECT id FROM difficulty WHERE label='INTERMEDIATE'),60,50,10,(SELECT id FROM visibility WHERE label='PUBLIC'),now()-interval '1401 hours',NULL),
  ('a73e363a-8e7a-fb56-d162-7574b15ef010','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06','Diocletian Palace & Dalmatian stone','Emperor Diocletian built his retirement palace in Split around 300 AD using local limestone and Roman planning. Compare it with the stone squares of Trogir and Dubrovnik, built from the same Dalmatian stone.',(SELECT id FROM country WHERE iso_code='HR'),(SELECT id FROM difficulty WHERE label='INTERMEDIATE'),120,100,10,(SELECT id FROM visibility WHERE label='PUBLIC'),now()-interval '1400 hours',NULL),
  ('15e50a92-e8f1-222d-1f1c-ed83cd8f162a','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06','Krka waterfalls and travertine','Krka waterfalls form where river water deposits travertine, a porous rock built up by moss and algae. Learn how the freshwater ecosystem, from fish to aquatic insects, depends on clean flow and carbonate chemistry.',(SELECT id FROM country WHERE iso_code='HR'),(SELECT id FROM difficulty WHERE label='INTERMEDIATE'),90,70,10,(SELECT id FROM visibility WHERE label='PUBLIC'),now()-interval '1399 hours',NULL),
  ('f8e8b584-3560-ea14-84e2-18f195a41830','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06','Klapa singing of Dalmatia','Klapa is an unaccompanied male vocal style from Dalmatia, sung in close harmony by groups who often sing without scores. UNESCO added klapa singing to its intangible heritage list in 2012.',(SELECT id FROM country WHERE iso_code='HR'),(SELECT id FROM difficulty WHERE label='BEGINNER'),30,40,10,(SELECT id FROM visibility WHERE label='PUBLIC'),now()-interval '1398 hours',NULL),
  ('90e1aa81-dafb-7e91-6d80-58a7c7738f4b','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06','Pelicans of Lake Skadar','Lake Skadar is a key breeding site for Dalmatian pelicans, which nest on rocky islets and reed-fringed shores. Learn how water levels, fishing and reed beds decide whether the colony succeeds each year.',(SELECT id FROM country WHERE iso_code='ME'),(SELECT id FROM difficulty WHERE label='BEGINNER'),45,40,10,(SELECT id FROM visibility WHERE label='PUBLIC'),now()-interval '1397 hours',NULL),
  ('f52831de-af99-80b3-0e7e-4f2e33507cf7','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06','Kotor walls and the Bay of Kotor','Kotor Old Town is enclosed by walls that climb the mountain behind it, linking the town to St John fortress. Learn how Venetian engineers designed the defenses and how the walls survived earthquakes and sieges.',(SELECT id FROM country WHERE iso_code='ME'),(SELECT id FROM difficulty WHERE label='INTERMEDIATE'),120,100,10,(SELECT id FROM visibility WHERE label='PUBLIC'),now()-interval '1396 hours',NULL),
  ('a25c8f57-2de4-48b0-dcd1-9546357bd85a','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06','Boka Bay fishing traditions','According to local legend, sailors from Perast built the island of Our Lady of the Rocks stone by stone. Learn how boats, nets and calm bay water shaped village life, and how the rite is still marked.',(SELECT id FROM country WHERE iso_code='ME'),(SELECT id FROM difficulty WHERE label='BEGINNER'),45,40,10,(SELECT id FROM visibility WHERE label='PUBLIC'),now()-interval '1395 hours',NULL),
  ('dbfb0fe5-06ec-a1a5-e9ec-64680c800791','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06','Hanami: cherry blossom viewing','Hanami is the seasonal custom of picnicking under blossoming cherry trees, practiced across Japan for centuries. Learn how the Japan Meteorological Agency forecasts bloom dates and why parks fill fast in spring.',(SELECT id FROM country WHERE iso_code='JP'),(SELECT id FROM difficulty WHERE label='BEGINNER'),60,50,10,(SELECT id FROM visibility WHERE label='PUBLIC'),now()-interval '1394 hours',NULL),
  ('e91e8c39-72f5-5cb7-67e0-86ef28c86ffb','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06','Kyoto golden and zen temples','Kinkaku-ji is covered in gold leaf and sits on a pond, while Kiyomizu-dera is built on wooden stilts over a hillside. Walk the Path of Philosophy and the torii of Fushimi Inari to see how temples fit into the city.',(SELECT id FROM country WHERE iso_code='JP'),(SELECT id FROM difficulty WHERE label='INTERMEDIATE'),120,100,10,(SELECT id FROM visibility WHERE label='PUBLIC'),now()-interval '1393 hours',NULL),
  ('35253233-99fa-f542-8d78-6a0f6fb77d1a','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06','Snow monkeys and hot springs','Japanese macaques at Jigokudani are among the northernmost wild monkeys on Earth and bathe in hot springs in winter. Learn how snow, food supply and social rank shape their behavior across a Nagano valley.',(SELECT id FROM country WHERE iso_code='JP'),(SELECT id FROM difficulty WHERE label='BEGINNER'),60,50,10,(SELECT id FROM visibility WHERE label='PUBLIC'),now()-interval '1392 hours',NULL),
  ('e8b63e9c-5897-4c39-1075-0e26df51d184','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06','Samurai and the Tokugawa shogunate','The Tokugawa shogunate ruled Japan from 1603 to 1868, a long era of strict class rules and peace. Study Nijo Castle, built in 1603 in Kyoto for Tokugawa Ieyasu, and how samurai served the state.',(SELECT id FROM country WHERE iso_code='JP'),(SELECT id FROM difficulty WHERE label='INTERMEDIATE'),150,120,10,(SELECT id FROM visibility WHERE label='PUBLIC'),now()-interval '1391 hours',NULL),
  ('2da6fbff-e269-93c1-64b0-6d2a92bfb01e','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06','Tsukiji fish markets and sushi','The old Tsukiji fish market moved to Toyosu in 2018, but its outer market kept the shops that sell fresh seafood. Learn how sushi chefs judge tuna and why knife work matters before you taste a single piece.',(SELECT id FROM country WHERE iso_code='JP'),(SELECT id FROM difficulty WHERE label='BEGINNER'),45,40,10,(SELECT id FROM visibility WHERE label='PUBLIC'),now()-interval '1390 hours',NULL),
  ('c386a406-8d1e-c728-5b21-2d0172da07ec','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06','Pyramids of Giza engineering','The Great Pyramid of Khufu was the tallest human-made structure for nearly four thousand years. Compare how its builders aligned the base to the compass and moved blocks with ramps and sledges.',(SELECT id FROM country WHERE iso_code='EG'),(SELECT id FROM difficulty WHERE label='INTERMEDIATE'),150,120,10,(SELECT id FROM visibility WHERE label='PUBLIC'),now()-interval '1389 hours',NULL),
  ('ab833395-50e7-bc6e-f4cd-f04fb2b1c852','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06','Ramadan lanterns & iftar in Cairo','During Ramadan, Cairo streets hang with fanous lanterns, and families break the fast at sunset. Learn the customs of Al-Muizz Street, a medieval Fatimid thoroughfare that fills with night markets.',(SELECT id FROM country WHERE iso_code='EG'),(SELECT id FROM difficulty WHERE label='BEGINNER'),45,40,10,(SELECT id FROM visibility WHERE label='PUBLIC'),now()-interval '1388 hours',NULL),
  ('fba4dfff-fb47-59e5-f4a5-f75db7e7654d','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06','Valley of the Kings & New Kingdom','New Kingdom pharaohs were buried in rock-cut tombs in the Valley of the Kings near Luxor, hidden from tomb robbers. Compare the tomb of Tutankhamun, found in 1922, with Karnak temple and the Egyptian Museum.',(SELECT id FROM country WHERE iso_code='EG'),(SELECT id FROM difficulty WHERE label='INTERMEDIATE'),120,100,10,(SELECT id FROM visibility WHERE label='PUBLIC'),now()-interval '1387 hours',NULL),
  ('398e6b5f-8f06-508a-705a-219ca89af941','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06','Nile crocodiles of Lake Nasser','Lake Nasser, created by the Aswan High Dam, is home to Nile crocodiles that adapted to new shores. Learn how Abu Simbel and the lake fish stocks link to crocodile feeding ecology.',(SELECT id FROM country WHERE iso_code='EG'),(SELECT id FROM difficulty WHERE label='INTERMEDIATE'),60,50,10,(SELECT id FROM visibility WHERE label='PUBLIC'),now()-interval '1386 hours',NULL),
  ('5bc4798a-d61e-7127-9696-5b0eb8b362b9','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06','Taj Mahal and Mughal symmetry','The Taj Mahal, completed around 1653, was built by Shah Jahan as a tomb for his wife Mumtaz Mahal. Study its symmetry, inlay work and gardens, then compare them with the red walls of Agra Fort.',(SELECT id FROM country WHERE iso_code='IN'),(SELECT id FROM difficulty WHERE label='INTERMEDIATE'),90,70,10,(SELECT id FROM visibility WHERE label='PUBLIC'),now()-interval '1385 hours',NULL),
  ('743d0ed2-3b15-b4ba-e11a-4a2a3077d950','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06','Holi, the festival of colours','Holi marks the arrival of spring and is celebrated with colored powder and water across India and abroad. Learn how stories, bonfires and street customs differ between northern and southern regions.',(SELECT id FROM country WHERE iso_code='IN'),(SELECT id FROM difficulty WHERE label='BEGINNER'),30,40,10,(SELECT id FROM visibility WHERE label='PUBLIC'),now()-interval '1384 hours',NULL),
  ('fcfd996e-ee24-568e-5158-f32e8f45db41','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06','Tigers of Ranthambore','Ranthambore, once a royal hunting ground, has one of the best-studied wild tiger populations in India. Learn how tigers use ruins and lakes, and how camera traps track individuals by stripe patterns.',(SELECT id FROM country WHERE iso_code='IN'),(SELECT id FROM difficulty WHERE label='INTERMEDIATE'),90,70,10,(SELECT id FROM visibility WHERE label='PUBLIC'),now()-interval '1383 hours',NULL),
  ('1af6b90a-db58-3a4f-3033-305fe33c3fbf','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06','Rajasthani miniature painting','Rajasthani miniatures were painted with fine brushes on paper and cloth, using mineral pigments and gold. Compare the palace painting of Jaipur City Palace and Amber Fort with the work of modern local painters.',(SELECT id FROM country WHERE iso_code='IN'),(SELECT id FROM difficulty WHERE label='INTERMEDIATE'),90,70,10,(SELECT id FROM visibility WHERE label='PUBLIC'),now()-interval '1382 hours',NULL),
  ('96033e2b-ff2a-0c9f-6c85-a0d723270207','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06','Machu Picchu: Inca terraces','Machu Picchu was built in the mid-1400s as a royal estate with terraces, temples and water channels. Learn how Inca stonework was fitted without mortar, and compare it with Sacsayhuaman in Cusco.',(SELECT id FROM country WHERE iso_code='PE'),(SELECT id FROM difficulty WHERE label='INTERMEDIATE'),150,120,10,(SELECT id FROM visibility WHERE label='PUBLIC'),now()-interval '1381 hours',NULL),
  ('7b88d3be-66f8-e72a-5923-1a9fd1077761','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06','Inti Raymi and the Inca calendar','Inti Raymi, the Festival of the Sun, is held in Cusco each June 24 and recreates a ritual of Inca times. Learn how solar alignments, Qorikancha and the Plaza de Armas tie the festival to the Inca calendar.',(SELECT id FROM country WHERE iso_code='PE'),(SELECT id FROM difficulty WHERE label='INTERMEDIATE'),60,50,10,(SELECT id FROM visibility WHERE label='PUBLIC'),now()-interval '1380 hours',NULL),
  ('4345587a-19a9-dc26-12a5-60852d276267','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06','Andean cloud forest hummingbirds','Hummingbirds in the Andean cloud forest feed on nectar from flowers shaped to fit their long bills. Learn why these birds need a steady supply of flowers through the year and how cloud forest rain shapes their habitat.',(SELECT id FROM country WHERE iso_code='PE'),(SELECT id FROM difficulty WHERE label='BEGINNER'),60,50,10,(SELECT id FROM visibility WHERE label='PUBLIC'),now()-interval '1379 hours',NULL),
  ('88ce3f74-dc1b-382d-3f6d-0c94e80175e9','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06','Great Barrier Reef coral bleaching','Mass bleaching happens when water stays too warm for weeks, making corals expel the algae that feed them. Study the 2016 and 2017 bleaching events and how Heron Island supports recovery research.',(SELECT id FROM country WHERE iso_code='AU'),(SELECT id FROM difficulty WHERE label='ADVANCED'),180,140,10,(SELECT id FROM visibility WHERE label='PUBLIC'),now()-interval '1378 hours',NULL),
  ('8c593b01-1d70-7df9-983a-e438a88ed45e','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06','Songlines and Uluru Dreaming','Songlines are paths across Australia that carry Dreaming stories and laws of Aboriginal peoples. Uluru is sacred to the Anangu people, who share management of the park, so its stories are told with care.',(SELECT id FROM country WHERE iso_code='AU'),(SELECT id FROM difficulty WHERE label='INTERMEDIATE'),60,50,10,(SELECT id FROM visibility WHERE label='PUBLIC'),now()-interval '1377 hours',NULL),
  ('76d4a5d7-4e13-8133-f888-b01fce045475','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06','Convict Australia: Port Arthur','Port Arthur in Tasmania held convicts from the 1830s until 1877 as a major penal settlement. Study the separate prison system, convict workshops and the stone buildings of the town.',(SELECT id FROM country WHERE iso_code='AU'),(SELECT id FROM difficulty WHERE label='INTERMEDIATE'),90,70,10,(SELECT id FROM visibility WHERE label='PUBLIC'),now()-interval '1376 hours',NULL),
  ('0ff7d552-52dd-6308-5eab-4e30e4052148','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06','Australian rules football at the MCG','Australian rules football was codified in Melbourne in 1859 and is played on large ovals with four goal posts. Learn how the MCG, opened in 1853, hosts the AFL Grand Final and how scoring works.',(SELECT id FROM country WHERE iso_code='AU'),(SELECT id FROM difficulty WHERE label='BEGINNER'),60,50,10,(SELECT id FROM visibility WHERE label='PUBLIC'),now()-interval '1375 hours',NULL),
  ('44c41739-d09d-b916-5908-e57acb5fe469','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06','Iceland hot springs & microbes','The hot springs of Iceland host heat-loving microbes that thrive where few other organisms can survive. Compare the Blue Lagoon with the geyser Strokkur and Thingvellir, where two tectonic plates separate.',(SELECT id FROM country WHERE iso_code='IS'),(SELECT id FROM difficulty WHERE label='INTERMEDIATE'),120,100,10,(SELECT id FROM visibility WHERE label='PUBLIC'),now()-interval '1374 hours',NULL),
