INSERT INTO course_version (id,course_id,version_number,title,description,difficulty_id,estimated_minutes,publication_status_id,created_by,created_at,published_at) VALUES
  ('a97937cc-2512-03d3-6fbc-1909ff7cdd22','efdd2a13-b3a7-94bf-7dc8-e7cf1ce35da1',1,'Bull riding & the corrida tradition','The corrida grew from Andalusian horsemanship into a ritual with set stages: picadors, banderillas and a final faena. Compare the 1785 ring at Ronda with Seville Maestranza and Las Ventas in Madrid, which opened in 1931.',(SELECT id FROM difficulty WHERE label='INTERMEDIATE'),90,(SELECT id FROM publication_status WHERE label='PUBLISHED'),'6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',now()-interval '1152 hours'),
  ('c7c454fc-4cd6-8351-fabb-416948658fa4','9870388e-825d-f5f2-0931-6e02d194c186',1,'Doñana wetlands & the Iberian lynx','Doñana marshes, dunes and pine forests shelter the Iberian lynx, one of the most endangered wild cats on Earth. Learn how seasonal floods drive bird migrations and why water management shapes the wetlands.',(SELECT id FROM difficulty WHERE label='INTERMEDIATE'),75,(SELECT id FROM publication_status WHERE label='PUBLISHED'),'6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',now()-interval '1152 hours'),
  ('b252cca9-6546-ed15-dd07-3b6343fd614c','350bab1d-9928-ea03-26a3-c836689e00e4',1,'Alhambra and Moorish geometry','The Alhambra is covered in geometric tilework of stars and polygons, cut and fitted by hand. Compare it with the Mezquita in Cordoba and the Real Alcazar in Seville, built by Moorish and Christian hands.',(SELECT id FROM difficulty WHERE label='INTERMEDIATE'),120,(SELECT id FROM publication_status WHERE label='PUBLISHED'),'6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',now()-interval '1152 hours'),
  ('b065cd93-b944-94d3-58d6-2d54c36b9247','97fa4b7c-8b34-d488-fd77-d7468402a740',1,'Flamenco rhythm & Andalusian guitar','Flamenco mixes song, guitar and handclapping in palos, each with its own rhythmic cycle called compas. Learn the patterns of alegrias and bulerias, then trace how Triana in Seville shaped the style.',(SELECT id FROM difficulty WHERE label='BEGINNER'),60,(SELECT id FROM publication_status WHERE label='PUBLISHED'),'6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',now()-interval '1152 hours'),
  ('947b6db6-dbd3-71dd-8a43-95e4c0947691','ac3da173-5818-0f05-1b5e-f6e0aadd1693',1,'Jamón ibérico & acorn-fed pigs','Iberian pigs that forage on acorns in oak dehesas produce jamón ibérico de bellota, cured for years. Learn how breed, diet and curing time set the grades and why the fat softens at low temperatures.',(SELECT id FROM difficulty WHERE label='BEGINNER'),45,(SELECT id FROM publication_status WHERE label='PUBLISHED'),'6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',now()-interval '1152 hours'),
  ('b010b8f9-47cf-4461-bddd-eaa03208a6e3','94e81c58-923a-fe34-9cae-40da0458dd4a',1,'Palio di Siena: the horse race','Twice a year, ten of the seventeen contrade race bareback horses around the Piazza del Campo. Learn how contrade loyalty and the blessing of horses turn one race into a year-long city event.',(SELECT id FROM difficulty WHERE label='BEGINNER'),60,(SELECT id FROM publication_status WHERE label='PUBLISHED'),'6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',now()-interval '1152 hours'),
  ('dad671e0-f5bc-2c69-3e0e-f8ae81dd6633','737dc601-c0db-a742-6fcb-669e81804ced',1,'Roman concrete and the Pantheon','Roman builders mixed volcanic ash with lime to make concrete that still holds the Pantheon dome. Compare the Pantheon with Pompeii, where Roman walls and mortar were preserved under ash after the eruption of 79 AD.',(SELECT id FROM difficulty WHERE label='ADVANCED'),150,(SELECT id FROM publication_status WHERE label='PUBLISHED'),'6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',now()-interval '1152 hours'),
  ('643a5d7a-5c86-b2ce-c179-813ff4005c37','7babf7a6-8cb1-f669-ea13-3da800aba052',1,'Mount Etna volcanic ecosystems','Mount Etna is one of the most active volcanoes on Earth, and new lava fields are colonized by pioneer plants. Study how ash soils, altitude zones and frequent eruptions shape this rare ecosystem.',(SELECT id FROM difficulty WHERE label='INTERMEDIATE'),90,(SELECT id FROM publication_status WHERE label='PUBLISHED'),'6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',now()-interval '1152 hours'),
  ('b9d539e4-1239-348e-4d2e-d1b42c36bbd7','bb355a7c-2359-e5ba-380f-04245216d600',1,'Parmigiano-Reggiano and dairy craft','Parmigiano-Reggiano is made only in a defined area of northern Italy from cow milk, salt and rennet, with no additives. Learn why wheels age for at least twelve months and how graders judge them by tapping.',(SELECT id FROM difficulty WHERE label='BEGINNER'),40,(SELECT id FROM publication_status WHERE label='PUBLISHED'),'6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',now()-interval '1152 hours'),
  ('f156d29e-81c2-b3f9-4496-cabf4cd6bc97','4af06a45-e646-448a-3066-9617c56b2a1d',1,'Olympia and the ancient Games','The Olympic Games began at Olympia in 776 BC according to tradition, with a single footrace as the first event. Trace how the Pythian and Panathenaic festivals spread athletic contests across the Greek world.',(SELECT id FROM difficulty WHERE label='BEGINNER'),60,(SELECT id FROM publication_status WHERE label='PUBLISHED'),'6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',now()-interval '1152 hours'),
  ('6d2e0a9f-80de-662e-ddcd-b43c64a9e069','499067d6-d442-856c-c629-ac98d2059602',1,'Delphi, the oracle and city-states','The oracle of Apollo at Delphi was consulted by city-states and rulers across the Mediterranean for centuries. Read the treasury inscriptions, then compare its politics with the Acropolis of Athens.',(SELECT id FROM difficulty WHERE label='INTERMEDIATE'),105,(SELECT id FROM publication_status WHERE label='PUBLISHED'),'6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',now()-interval '1152 hours'),
  ('402553b4-3c23-7bde-b459-8f0621cb3078','12b0a2d2-4a3a-371d-74ab-6038c42ee3c3',1,'Loggerhead turtles of Zakynthos','Loggerhead sea turtles nest on Zakynthos beaches and often return to the shores where they hatched. Learn how nest protection, beach lighting and boat traffic affect how many hatchlings reach the sea.',(SELECT id FROM difficulty WHERE label='BEGINNER'),75,(SELECT id FROM publication_status WHERE label='PUBLISHED'),'6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',now()-interval '1152 hours'),
  ('9024b54c-9021-5e10-9f5a-24c96208abea','5b2daa65-e4ca-7c84-1de1-0d0e949d5b80',1,'Petanque and Provence village games','Petanque was developed in La Ciotat in 1907, when a player with rheumatism invented a standing-still throw. Learn the rules of boules, how the cochonnet is placed and why the game suits village squares.',(SELECT id FROM difficulty WHERE label='BEGINNER'),30,(SELECT id FROM publication_status WHERE label='PUBLISHED'),'6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',now()-interval '1152 hours'),
  ('400f1a96-47ce-9bae-621e-6abf15d4d703','7b5bb64d-485d-59ed-e150-85b738ec22b2',1,'Monet gardens at Giverny','Claude Monet reworked his Giverny garden into a painting subject, with a water garden and a Japanese footbridge. Compare his water lily series with how light and colour change across a single summer.',(SELECT id FROM difficulty WHERE label='BEGINNER'),75,(SELECT id FROM publication_status WHERE label='PUBLISHED'),'6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',now()-interval '1152 hours'),
  ('1459fdd7-154a-eea6-68d3-d953a8ec0b18','dd0f3cf9-e34d-c42c-d8d7-7342a809b740',1,'Camargue flamingos and salt marshes','The Camargue delta hosts large numbers of greater flamingos, which feed in shallow lagoons and salt pans. Learn how river sediment, tides and salinity create bird habitats and why grazing bulls shape the land.',(SELECT id FROM difficulty WHERE label='INTERMEDIATE'),90,(SELECT id FROM publication_status WHERE label='PUBLISHED'),'6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',now()-interval '1152 hours'),
  ('53f62afe-6cf7-fba8-0780-a77e20e355db','51f6cc88-c8ea-91c9-65ed-18e5e1c65a0b',1,'Champagne and the Marne valley','Champagne is sparkling wine made only in its namesake region of France, fermented a second time in the bottle. Learn the traditional method, from blending base wines to riddling, and why chalk soils matter.',(SELECT id FROM difficulty WHERE label='INTERMEDIATE'),60,(SELECT id FROM publication_status WHERE label='PUBLISHED'),'6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',now()-interval '1152 hours'),
  ('256ae34e-af58-9584-a585-ad1c8820b421','a73e363a-8e7a-fb56-d162-7574b15ef010',1,'Diocletian Palace & Dalmatian stone','Emperor Diocletian built his retirement palace in Split around 300 AD using local limestone and Roman planning. Compare it with the stone squares of Trogir and Dubrovnik, built from the same Dalmatian stone.',(SELECT id FROM difficulty WHERE label='INTERMEDIATE'),120,(SELECT id FROM publication_status WHERE label='PUBLISHED'),'6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',now()-interval '1152 hours'),
  ('acb95d68-996c-f7bf-f204-8fde6898e960','15e50a92-e8f1-222d-1f1c-ed83cd8f162a',1,'Krka waterfalls and travertine','Krka waterfalls form where river water deposits travertine, a porous rock built up by moss and algae. Learn how the freshwater ecosystem, from fish to aquatic insects, depends on clean flow and carbonate chemistry.',(SELECT id FROM difficulty WHERE label='INTERMEDIATE'),90,(SELECT id FROM publication_status WHERE label='PUBLISHED'),'6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',now()-interval '1152 hours'),
  ('25ad0d08-e30d-7d79-bb3b-ac927b767c6b','f8e8b584-3560-ea14-84e2-18f195a41830',1,'Klapa singing of Dalmatia','Klapa is an unaccompanied male vocal style from Dalmatia, sung in close harmony by groups who often sing without scores. UNESCO added klapa singing to its intangible heritage list in 2012.',(SELECT id FROM difficulty WHERE label='BEGINNER'),30,(SELECT id FROM publication_status WHERE label='PUBLISHED'),'6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',now()-interval '1152 hours'),
  ('cd9d80c7-abe7-2cc5-cfe0-e08a73775923','90e1aa81-dafb-7e91-6d80-58a7c7738f4b',1,'Pelicans of Lake Skadar','Lake Skadar is a key breeding site for Dalmatian pelicans, which nest on rocky islets and reed-fringed shores. Learn how water levels, fishing and reed beds decide whether the colony succeeds each year.',(SELECT id FROM difficulty WHERE label='BEGINNER'),45,(SELECT id FROM publication_status WHERE label='PUBLISHED'),'6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',now()-interval '1152 hours'),
  ('7a26311a-74c3-d29c-5f6e-8bd79a80f9a3','f52831de-af99-80b3-0e7e-4f2e33507cf7',1,'Kotor walls and the Bay of Kotor','Kotor Old Town is enclosed by walls that climb the mountain behind it, linking the town to St John fortress. Learn how Venetian engineers designed the defenses and how the walls survived earthquakes and sieges.',(SELECT id FROM difficulty WHERE label='INTERMEDIATE'),120,(SELECT id FROM publication_status WHERE label='PUBLISHED'),'6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',now()-interval '1152 hours'),
  ('4c6b258f-a039-3bba-bbfb-b2ea6415b665','a25c8f57-2de4-48b0-dcd1-9546357bd85a',1,'Boka Bay fishing traditions','According to local legend, sailors from Perast built the island of Our Lady of the Rocks stone by stone. Learn how boats, nets and calm bay water shaped village life, and how the rite is still marked.',(SELECT id FROM difficulty WHERE label='BEGINNER'),45,(SELECT id FROM publication_status WHERE label='PUBLISHED'),'6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',now()-interval '1152 hours'),
  ('985a453b-d244-5bf3-cd4b-c46649638454','dbfb0fe5-06ec-a1a5-e9ec-64680c800791',1,'Hanami: cherry blossom viewing','Hanami is the seasonal custom of picnicking under blossoming cherry trees, practiced across Japan for centuries. Learn how the Japan Meteorological Agency forecasts bloom dates and why parks fill fast in spring.',(SELECT id FROM difficulty WHERE label='BEGINNER'),60,(SELECT id FROM publication_status WHERE label='PUBLISHED'),'6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',now()-interval '1152 hours'),
  ('48266f01-be0a-dfb1-2397-44b630c54278','e91e8c39-72f5-5cb7-67e0-86ef28c86ffb',1,'Kyoto golden and zen temples','Kinkaku-ji is covered in gold leaf and sits on a pond, while Kiyomizu-dera is built on wooden stilts over a hillside. Walk the Path of Philosophy and the torii of Fushimi Inari to see how temples fit into the city.',(SELECT id FROM difficulty WHERE label='INTERMEDIATE'),120,(SELECT id FROM publication_status WHERE label='PUBLISHED'),'6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',now()-interval '1152 hours'),
  ('3846297e-adb3-daac-cc5a-bf386a353d38','35253233-99fa-f542-8d78-6a0f6fb77d1a',1,'Snow monkeys and hot springs','Japanese macaques at Jigokudani are among the northernmost wild monkeys on Earth and bathe in hot springs in winter. Learn how snow, food supply and social rank shape their behavior across a Nagano valley.',(SELECT id FROM difficulty WHERE label='BEGINNER'),60,(SELECT id FROM publication_status WHERE label='PUBLISHED'),'6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',now()-interval '1152 hours'),
  ('e4c29217-3223-14d3-dbd9-90cfbd34d5e6','e8b63e9c-5897-4c39-1075-0e26df51d184',1,'Samurai and the Tokugawa shogunate','The Tokugawa shogunate ruled Japan from 1603 to 1868, a long era of strict class rules and peace. Study Nijo Castle, built in 1603 in Kyoto for Tokugawa Ieyasu, and how samurai served the state.',(SELECT id FROM difficulty WHERE label='INTERMEDIATE'),150,(SELECT id FROM publication_status WHERE label='PUBLISHED'),'6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',now()-interval '1152 hours'),
  ('37ea4185-14bc-01ca-8368-3120e7a47774','2da6fbff-e269-93c1-64b0-6d2a92bfb01e',1,'Tsukiji fish markets and sushi','The old Tsukiji fish market moved to Toyosu in 2018, but its outer market kept the shops that sell fresh seafood. Learn how sushi chefs judge tuna and why knife work matters before you taste a single piece.',(SELECT id FROM difficulty WHERE label='BEGINNER'),45,(SELECT id FROM publication_status WHERE label='PUBLISHED'),'6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',now()-interval '1152 hours'),
  ('807a65d3-fffa-713e-bbc4-7d69d8dd3269','c386a406-8d1e-c728-5b21-2d0172da07ec',1,'Pyramids of Giza engineering','The Great Pyramid of Khufu was the tallest human-made structure for nearly four thousand years. Compare how its builders aligned the base to the compass and moved blocks with ramps and sledges.',(SELECT id FROM difficulty WHERE label='INTERMEDIATE'),150,(SELECT id FROM publication_status WHERE label='PUBLISHED'),'6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',now()-interval '1152 hours'),
  ('d79a7be3-f135-59b6-a84b-4eea05e8af42','ab833395-50e7-bc6e-f4cd-f04fb2b1c852',1,'Ramadan lanterns & iftar in Cairo','During Ramadan, Cairo streets hang with fanous lanterns, and families break the fast at sunset. Learn the customs of Al-Muizz Street, a medieval Fatimid thoroughfare that fills with night markets.',(SELECT id FROM difficulty WHERE label='BEGINNER'),45,(SELECT id FROM publication_status WHERE label='PUBLISHED'),'6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',now()-interval '1152 hours'),
  ('44eb0942-0bc2-df19-537e-083d1d2b2c3a','fba4dfff-fb47-59e5-f4a5-f75db7e7654d',1,'Valley of the Kings & New Kingdom','New Kingdom pharaohs were buried in rock-cut tombs in the Valley of the Kings near Luxor, hidden from tomb robbers. Compare the tomb of Tutankhamun, found in 1922, with Karnak temple and the Egyptian Museum.',(SELECT id FROM difficulty WHERE label='INTERMEDIATE'),120,(SELECT id FROM publication_status WHERE label='PUBLISHED'),'6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',now()-interval '1152 hours'),
  ('3ed384cc-4ae8-d992-c355-2b9839e0c898','398e6b5f-8f06-508a-705a-219ca89af941',1,'Nile crocodiles of Lake Nasser','Lake Nasser, created by the Aswan High Dam, is home to Nile crocodiles that adapted to new shores. Learn how Abu Simbel and the lake fish stocks link to crocodile feeding ecology.',(SELECT id FROM difficulty WHERE label='INTERMEDIATE'),60,(SELECT id FROM publication_status WHERE label='PUBLISHED'),'6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',now()-interval '1152 hours'),
  ('dcd4ad1a-441d-d0d3-5bb7-b2c309f72e63','5bc4798a-d61e-7127-9696-5b0eb8b362b9',1,'Taj Mahal and Mughal symmetry','The Taj Mahal, completed around 1653, was built by Shah Jahan as a tomb for his wife Mumtaz Mahal. Study its symmetry, inlay work and gardens, then compare them with the red walls of Agra Fort.',(SELECT id FROM difficulty WHERE label='INTERMEDIATE'),90,(SELECT id FROM publication_status WHERE label='PUBLISHED'),'6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',now()-interval '1152 hours'),
  ('8905a392-c478-30ae-b613-766b76a42304','743d0ed2-3b15-b4ba-e11a-4a2a3077d950',1,'Holi, the festival of colours','Holi marks the arrival of spring and is celebrated with colored powder and water across India and abroad. Learn how stories, bonfires and street customs differ between northern and southern regions.',(SELECT id FROM difficulty WHERE label='BEGINNER'),30,(SELECT id FROM publication_status WHERE label='PUBLISHED'),'6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',now()-interval '1152 hours'),
  ('f189a399-2e83-4755-69d7-1b47394d95ae','fcfd996e-ee24-568e-5158-f32e8f45db41',1,'Tigers of Ranthambore','Ranthambore, once a royal hunting ground, has one of the best-studied wild tiger populations in India. Learn how tigers use ruins and lakes, and how camera traps track individuals by stripe patterns.',(SELECT id FROM difficulty WHERE label='INTERMEDIATE'),90,(SELECT id FROM publication_status WHERE label='PUBLISHED'),'6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',now()-interval '1152 hours'),
  ('55489e18-692c-cbcd-471b-02c4f9caea40','1af6b90a-db58-3a4f-3033-305fe33c3fbf',1,'Rajasthani miniature painting','Rajasthani miniatures were painted with fine brushes on paper and cloth, using mineral pigments and gold. Compare the palace painting of Jaipur City Palace and Amber Fort with the work of modern local painters.',(SELECT id FROM difficulty WHERE label='INTERMEDIATE'),90,(SELECT id FROM publication_status WHERE label='PUBLISHED'),'6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',now()-interval '1152 hours'),
  ('54d9c4a3-6adb-4140-55d6-3c6b5f05e797','96033e2b-ff2a-0c9f-6c85-a0d723270207',1,'Machu Picchu: Inca terraces','Machu Picchu was built in the mid-1400s as a royal estate with terraces, temples and water channels. Learn how Inca stonework was fitted without mortar, and compare it with Sacsayhuaman in Cusco.',(SELECT id FROM difficulty WHERE label='INTERMEDIATE'),150,(SELECT id FROM publication_status WHERE label='PUBLISHED'),'6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',now()-interval '1152 hours'),
  ('0a9f65a3-426a-71ea-b5e6-1e686789dc93','7b88d3be-66f8-e72a-5923-1a9fd1077761',1,'Inti Raymi and the Inca calendar','Inti Raymi, the Festival of the Sun, is held in Cusco each June 24 and recreates a ritual of Inca times. Learn how solar alignments, Qorikancha and the Plaza de Armas tie the festival to the Inca calendar.',(SELECT id FROM difficulty WHERE label='INTERMEDIATE'),60,(SELECT id FROM publication_status WHERE label='PUBLISHED'),'6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',now()-interval '1152 hours'),
  ('0232b4f7-e279-5ba9-f241-a9ac1ed8073c','4345587a-19a9-dc26-12a5-60852d276267',1,'Andean cloud forest hummingbirds','Hummingbirds in the Andean cloud forest feed on nectar from flowers shaped to fit their long bills. Learn why these birds need a steady supply of flowers through the year and how cloud forest rain shapes their habitat.',(SELECT id FROM difficulty WHERE label='BEGINNER'),60,(SELECT id FROM publication_status WHERE label='PUBLISHED'),'6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',now()-interval '1152 hours'),
  ('9b8ddb18-ffb7-8c78-09d3-35f9a4fa0086','88ce3f74-dc1b-382d-3f6d-0c94e80175e9',1,'Great Barrier Reef coral bleaching','Mass bleaching happens when water stays too warm for weeks, making corals expel the algae that feed them. Study the 2016 and 2017 bleaching events and how Heron Island supports recovery research.',(SELECT id FROM difficulty WHERE label='ADVANCED'),180,(SELECT id FROM publication_status WHERE label='PUBLISHED'),'6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',now()-interval '1152 hours'),
  ('fbbe19ee-464a-d694-5371-17fb2d6204ff','8c593b01-1d70-7df9-983a-e438a88ed45e',1,'Songlines and Uluru Dreaming','Songlines are paths across Australia that carry Dreaming stories and laws of Aboriginal peoples. Uluru is sacred to the Anangu people, who share management of the park, so its stories are told with care.',(SELECT id FROM difficulty WHERE label='INTERMEDIATE'),60,(SELECT id FROM publication_status WHERE label='PUBLISHED'),'6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',now()-interval '1152 hours'),
  ('22756581-35fc-de1f-d6ec-af48c7464c88','76d4a5d7-4e13-8133-f888-b01fce045475',1,'Convict Australia: Port Arthur','Port Arthur in Tasmania held convicts from the 1830s until 1877 as a major penal settlement. Study the separate prison system, convict workshops and the stone buildings of the town.',(SELECT id FROM difficulty WHERE label='INTERMEDIATE'),90,(SELECT id FROM publication_status WHERE label='PUBLISHED'),'6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',now()-interval '1152 hours'),
  ('a0f3e0fa-88c0-2f0a-f629-356d4fdfa719','0ff7d552-52dd-6308-5eab-4e30e4052148',1,'Australian rules football at the MCG','Australian rules football was codified in Melbourne in 1859 and is played on large ovals with four goal posts. Learn how the MCG, opened in 1853, hosts the AFL Grand Final and how scoring works.',(SELECT id FROM difficulty WHERE label='BEGINNER'),60,(SELECT id FROM publication_status WHERE label='PUBLISHED'),'6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',now()-interval '1152 hours'),
  ('3ad5114f-7dd4-8a0c-a2cf-830f1e2f047b','44c41739-d09d-b916-5908-e57acb5fe469',1,'Iceland hot springs & microbes','The hot springs of Iceland host heat-loving microbes that thrive where few other organisms can survive. Compare the Blue Lagoon with the geyser Strokkur and Thingvellir, where two tectonic plates separate.',(SELECT id FROM difficulty WHERE label='INTERMEDIATE'),120,(SELECT id FROM publication_status WHERE label='PUBLISHED'),'6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',now()-interval '1152 hours'),
  ('b1694848-4166-6425-b02d-210bce44c0bc','dd789449-c621-a058-735b-7dcc3407b095',1,'Glima: the ancient wrestling of Iceland','Glima is the traditional wrestling style of Iceland, with throws that use a belt, balance and leg work. Learn its main holds and how Icelandic clubs still teach it to children and adults.',(SELECT id FROM difficulty WHERE label='BEGINNER'),30,(SELECT id FROM publication_status WHERE label='PUBLISHED'),'6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',now()-interval '1152 hours'),
  ('4bb079b9-6bae-7125-1a7e-2f07b1388171','b566c2c2-4f85-58b7-4cd1-8eef5d941be6',1,'Thorrablot: Iceland midwinter feast','Thorrablot is an Icelandic midwinter feast held in January and February, centered on preserved foods. Learn how the 19th-century revival shaped its menu, from fermented shark to singed sheep head.',(SELECT id FROM difficulty WHERE label='BEGINNER'),30,(SELECT id FROM publication_status WHERE label='PUBLISHED'),'6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',now()-interval '1152 hours'),
  ('d743688f-a9f3-5239-0cdc-c7fd345e427b','6e9acdc3-fa17-8571-e149-cd75604ce87e',1,'Optional metadata example',NULL,(SELECT id FROM difficulty WHERE label='BEGINNER'),NULL,(SELECT id FROM publication_status WHERE label='PUBLISHED'),'6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',now()-interval '1152 hours'),
  ('f94359ad-8378-437c-7c25-26e79741a2e5','30265040-709b-d212-2e03-16ea3ea3332b',1,'Owned archived course example','A granted private archived course remains in your library.',(SELECT id FROM difficulty WHERE label='BEGINNER'),20,(SELECT id FROM publication_status WHERE label='PUBLISHED'),'6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',now()-interval '1152 hours'),
  ('eba0039a-decd-ceea-1ec4-a612b835f8e2','0cbc5b03-99e7-9c68-7ba8-312ed4db1319',1,'Unpublished demo course (hidden)','This course must not appear in the public catalogue.',(SELECT id FROM difficulty WHERE label='BEGINNER'),15,'9c74f449-1cb8-5745-a7f4-6cc7ef718481','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',now()-interval '1200 hours',NULL)
