INSERT INTO event (id,name,description,organizer_id,country_id,place_id,external_registration_url,starts_at,ends_at,timezone,is_free) VALUES
  ('e5f1cd87-2f6b-465d-dc6c-9a264a7de16c','Explaining AI to Your Grandparents','A relaxed lecture on what AI actually does, without jargon or scare stories. Bring a question your family keeps asking and leave with a simple answer.','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',(SELECT id FROM country WHERE iso_code='ME'),'89f98048-f21d-ef7e-f134-eb3a27a8ae15','https://example.com/events/e1',((date_trunc('day',now() AT TIME ZONE 'Europe/Podgorica')+interval '0 days'+time '18:00') AT TIME ZONE 'Europe/Podgorica'),((date_trunc('day',now() AT TIME ZONE 'Europe/Podgorica')+interval '0 days'+time '18:00') AT TIME ZONE 'Europe/Podgorica')+interval '2 hours','Europe/Podgorica',true),
  ('98acd864-c413-9579-67a9-9631beee41c9','Hands-On Prompt Lab','Practise writing clear prompts and compare how different models respond. Laptops are provided and no coding experience is needed.','1912d8a0-ca7a-4d6f-d457-7b1536472244',(SELECT id FROM country WHERE iso_code='ME'),'5536e522-6c83-dbd4-f66d-594fb4f2d0dd','https://example.com/events/e2',((date_trunc('day',now() AT TIME ZONE 'Europe/Podgorica')+interval '0 days'+time '10:00') AT TIME ZONE 'Europe/Podgorica'),((date_trunc('day',now() AT TIME ZONE 'Europe/Podgorica')+interval '0 days'+time '10:00') AT TIME ZONE 'Europe/Podgorica')+interval '2 hours','Europe/Podgorica',false),
  ('87597890-60f1-6e22-89f5-8b0fdf57b31d','Film Night: The Social Dilemma','A screening of the documentary on how recommendation systems shape attention. A short discussion follows, led by a local media educator.','265494df-c98d-acbb-dc05-426a45d520f7',(SELECT id FROM country WHERE iso_code='ME'),'3f16a29a-6bc6-bb9d-33dd-fafe83f73fab','https://example.com/events/e3',((date_trunc('day',now() AT TIME ZONE 'Europe/Podgorica')+interval '0 days'+time '20:00') AT TIME ZONE 'Europe/Podgorica'),((date_trunc('day',now() AT TIME ZONE 'Europe/Podgorica')+interval '0 days'+time '20:00') AT TIME ZONE 'Europe/Podgorica')+interval '2 hours','Europe/Podgorica',true),
  ('2e36cb0e-2701-52eb-3f10-c723d82e99bc','Sunrise Trail Run and Map Reading','An easy early run along the river, with a stop to learn paper map reading. Pace groups are arranged for all levels.','6abd4bc9-463d-2bfe-42d3-c55d6d3f9e77',(SELECT id FROM country WHERE iso_code='ME'),'d35b4c65-c736-7de0-d25c-063fe7452196','https://example.com/events/e4',((date_trunc('day',now() AT TIME ZONE 'Europe/Podgorica')+interval '0 days'+time '09:00') AT TIME ZONE 'Europe/Podgorica'),((date_trunc('day',now() AT TIME ZONE 'Europe/Podgorica')+interval '0 days'+time '09:00') AT TIME ZONE 'Europe/Podgorica')+interval '2 hours','Europe/Podgorica',true),
  ('784ba7e6-7d97-7106-9349-91774a8b5a13','Stories in Stone: Citadel Walk','A guided walk through the Budva citadel, tracing centuries of trade and defence. Participants check the historical claims against sources on their phones.','c57bab45-6cb6-01fa-d479-a04f4685bcee',(SELECT id FROM country WHERE iso_code='ME'),'5bbad79b-e9e7-854c-4b03-2390ff0856e3','https://example.com/events/e5',((date_trunc('day',now() AT TIME ZONE 'Europe/Podgorica')+interval '0 days'+time '11:00') AT TIME ZONE 'Europe/Podgorica'),((date_trunc('day',now() AT TIME ZONE 'Europe/Podgorica')+interval '0 days'+time '11:00') AT TIME ZONE 'Europe/Podgorica')+interval '2 hours','Europe/Podgorica',false),
  ('dea63996-be8e-64dd-5508-a1afa7ae45d9','Open-Water Swim and Sea Science','A supervised beginner swim followed by a short talk on coastal ecology. Water quality data from the bay is shown and explained on the beach.','413f097e-3809-951d-91e0-0761eec1f67c',(SELECT id FROM country WHERE iso_code='ME'),'00724b11-5589-c65e-9142-fa93be582480','https://example.com/events/e6',((date_trunc('day',now() AT TIME ZONE 'Europe/Podgorica')+interval '0 days'+time '17:30') AT TIME ZONE 'Europe/Podgorica'),((date_trunc('day',now() AT TIME ZONE 'Europe/Podgorica')+interval '0 days'+time '17:30') AT TIME ZONE 'Europe/Podgorica')+interval '2 hours','Europe/Podgorica',false),
  ('8ceac5b6-b351-8d9a-cb51-2145c5455a19','Build a Tiny Chatbot','Build a simple rule-based chatbot in one evening, then see where it breaks. The session ends with a discussion of what makes a chatbot seem smart.','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',(SELECT id FROM country WHERE iso_code='ME'),'b052d464-971b-0c89-0363-064b07f3476e','https://example.com/events/e7',((date_trunc('day',now() AT TIME ZONE 'Europe/Podgorica')+interval '0 days'+time '19:00') AT TIME ZONE 'Europe/Podgorica'),((date_trunc('day',now() AT TIME ZONE 'Europe/Podgorica')+interval '0 days'+time '19:00') AT TIME ZONE 'Europe/Podgorica')+interval '2 hours','Europe/Podgorica',false),
  ('42bc01e4-a029-63de-9ad6-b9d52387a50f','Ancient Bay, Modern Data','How sea level, tides and historical records are now analysed with open data tools. The talk uses Kotor Bay examples throughout.','1912d8a0-ca7a-4d6f-d457-7b1536472244',(SELECT id FROM country WHERE iso_code='ME'),'758e50fd-1db0-09f8-2a39-6041d603b04d','https://example.com/events/e8',((date_trunc('day',now() AT TIME ZONE 'Europe/Podgorica')+interval '0 days'+time '17:00') AT TIME ZONE 'Europe/Podgorica'),((date_trunc('day',now() AT TIME ZONE 'Europe/Podgorica')+interval '0 days'+time '17:00') AT TIME ZONE 'Europe/Podgorica')+interval '2 hours','Europe/Podgorica',true),
  ('ff796248-80d5-2478-5afa-a8c5168fc00c','How Language Models Think','An accessible explanation of tokens, probabilities and why models can sound confident and still be wrong. No maths background is required.','265494df-c98d-acbb-dc05-426a45d520f7',(SELECT id FROM country WHERE iso_code='ME'),'6705f2cf-bc3b-a4c2-42be-6ab04c7f44cf','https://example.com/events/e9',((date_trunc('day',now() AT TIME ZONE 'Europe/Podgorica')+interval '1 days'+time '18:30') AT TIME ZONE 'Europe/Podgorica'),((date_trunc('day',now() AT TIME ZONE 'Europe/Podgorica')+interval '1 days'+time '18:30') AT TIME ZONE 'Europe/Podgorica')+interval '2 hours','Europe/Podgorica',true),
  ('b06988c7-ff85-5c21-a3b4-d0cfc03fd661','From Spreadsheets to Insights','Turn a messy spreadsheet into a clear chart, then ask an AI assistant to check the result. Bring a small dataset of your own if you have one.','6abd4bc9-463d-2bfe-42d3-c55d6d3f9e77',(SELECT id FROM country WHERE iso_code='ME'),'77d96c78-e8cd-689d-da05-cab54280d9eb','https://example.com/events/e10',((date_trunc('day',now() AT TIME ZONE 'Europe/Podgorica')+interval '1 days'+time '11:00') AT TIME ZONE 'Europe/Podgorica'),((date_trunc('day',now() AT TIME ZONE 'Europe/Podgorica')+interval '1 days'+time '11:00') AT TIME ZONE 'Europe/Podgorica')+interval '2 hours','Europe/Podgorica',false),
  ('6218984c-fcb4-8269-0b6a-42356e8e06e0','Maps and Memories','An exhibition of historic maps of the Bar coast, shown next to family photographs lent by local residents. Curators give short tours on weekends.','c57bab45-6cb6-01fa-d479-a04f4685bcee',(SELECT id FROM country WHERE iso_code='ME'),'b25c45e2-17f2-a826-f066-4b828047f21f','https://example.com/events/e11',((date_trunc('day',now() AT TIME ZONE 'Europe/Podgorica')+interval '1 days'+time '10:00') AT TIME ZONE 'Europe/Podgorica'),((date_trunc('day',now() AT TIME ZONE 'Europe/Podgorica')+interval '1 days'+time '10:00') AT TIME ZONE 'Europe/Podgorica')+interval '2 hours','Europe/Podgorica',true),
  ('5a18c221-ff15-d1a7-ea9e-35343a0aac90','Can Machines Care? Philosophy Cafe','An open conversation about empathy, responsibility and whether machines can care. Everyone is welcome and no reading is required.','413f097e-3809-951d-91e0-0761eec1f67c',(SELECT id FROM country WHERE iso_code='ME'),'d97ce832-b1ba-bfad-c265-4b56a8b2434e','https://example.com/events/e12',((date_trunc('day',now() AT TIME ZONE 'Europe/Podgorica')+interval '-2 days'+time '19:00') AT TIME ZONE 'Europe/Podgorica'),((date_trunc('day',now() AT TIME ZONE 'Europe/Podgorica')+interval '-2 days'+time '19:00') AT TIME ZONE 'Europe/Podgorica')+interval '2 hours','Europe/Podgorica',false),
  ('0dfb28d0-401c-1699-0d50-96d75d486f72','Photo Walk Through the Old Town','A two-hour walk through the old town with a guide on composition and light. Bring any camera, including a phone.','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',(SELECT id FROM country WHERE iso_code='ME'),'da44aa2a-2234-b966-9092-7bec032f5744','https://example.com/events/e13',((date_trunc('day',now() AT TIME ZONE 'Europe/Podgorica')+interval '-1 days'+time '16:00') AT TIME ZONE 'Europe/Podgorica'),((date_trunc('day',now() AT TIME ZONE 'Europe/Podgorica')+interval '-1 days'+time '16:00') AT TIME ZONE 'Europe/Podgorica')+interval '2 hours','Europe/Podgorica',true),
  ('3d8042e0-ba11-b410-e26e-006df3f0bf00','Design for the Coast','Product and architecture work made for coastal conditions, with a talk on using AI in early design sketches. Entry is by timed slot.','1912d8a0-ca7a-4d6f-d457-7b1536472244',(SELECT id FROM country WHERE iso_code='ME'),'d78e22f2-4e12-f703-ef5a-cb5aa43cd2c2','https://example.com/events/e14',((date_trunc('day',now() AT TIME ZONE 'Europe/Podgorica')+interval '3 days'+time '11:00') AT TIME ZONE 'Europe/Podgorica'),((date_trunc('day',now() AT TIME ZONE 'Europe/Podgorica')+interval '3 days'+time '11:00') AT TIME ZONE 'Europe/Podgorica')+interval '2 hours','Europe/Podgorica',false),
  ('97ed8140-3d21-25a1-c1b7-26b1d6b74957','Documentary Night: Machines at Sea','A documentary about autonomous ships and maritime safety, followed by a Q&A with a naval engineer. Seating is limited.','265494df-c98d-acbb-dc05-426a45d520f7',(SELECT id FROM country WHERE iso_code='ME'),'355c4d66-a7de-e176-0d37-62a321ec8ad9','https://example.com/events/e15',((date_trunc('day',now() AT TIME ZONE 'Europe/Podgorica')+interval '2 days'+time '19:30') AT TIME ZONE 'Europe/Podgorica'),((date_trunc('day',now() AT TIME ZONE 'Europe/Podgorica')+interval '2 days'+time '19:30') AT TIME ZONE 'Europe/Podgorica')+interval '2 hours','Europe/Podgorica',false),
  ('489dee89-dcbb-c23d-a416-5281f327f11d','Night Run Clinic','A coach-led session on safe night running, reflective gear and pacing. It ends with a short easy loop. Headlamps are recommended.','6abd4bc9-463d-2bfe-42d3-c55d6d3f9e77',(SELECT id FROM country WHERE iso_code='ME'),'54b306bf-58f2-0b6d-7fb8-b088353bc55c','https://example.com/events/e16',((date_trunc('day',now() AT TIME ZONE 'Europe/Podgorica')+interval '5 days'+time '19:30') AT TIME ZONE 'Europe/Podgorica'),((date_trunc('day',now() AT TIME ZONE 'Europe/Podgorica')+interval '5 days'+time '19:30') AT TIME ZONE 'Europe/Podgorica')+interval '2 hours','Europe/Podgorica',false),
  ('fe0c08e8-49e0-fdaf-3bd5-b79a843f2ed1','The Ethics of Smart Cities','A lecture on surveillance, data collection and fairness in city services. Examples come from public transport and parking systems in Podgorica.','c57bab45-6cb6-01fa-d479-a04f4685bcee',(SELECT id FROM country WHERE iso_code='ME'),'04827a33-54b8-9ee1-941b-1e74cab511f5','https://example.com/events/e17',((date_trunc('day',now() AT TIME ZONE 'Europe/Podgorica')+interval '7 days'+time '18:00') AT TIME ZONE 'Europe/Podgorica'),((date_trunc('day',now() AT TIME ZONE 'Europe/Podgorica')+interval '7 days'+time '18:00') AT TIME ZONE 'Europe/Podgorica')+interval '2 hours','Europe/Podgorica',true),
  ('be6602da-526e-4b17-c036-d8f0bfda5732','Sketch the Sea with AI Tools','Sketch a harbour view by hand, then explore how AI image tools reinterpret the same scene. Materials are provided on site.','413f097e-3809-951d-91e0-0761eec1f67c',(SELECT id FROM country WHERE iso_code='ME'),'8c8d23df-1a7a-ea8c-53d1-caecaa0faac2','https://example.com/events/e18',((date_trunc('day',now() AT TIME ZONE 'Europe/Podgorica')+interval '4 days'+time '16:00') AT TIME ZONE 'Europe/Podgorica'),((date_trunc('day',now() AT TIME ZONE 'Europe/Podgorica')+interval '4 days'+time '16:00') AT TIME ZONE 'Europe/Podgorica')+interval '2 hours','Europe/Podgorica',false),
  ('3e6649bd-3bcc-0f66-b025-ef9ea4146b3b','The Future of Work','A short film series on automation and jobs, followed by a panel of local employers and trainers. The panel covers reskilling options.','6bfee6fe-eb3f-dd44-cce0-a3045bde3b06',(SELECT id FROM country WHERE iso_code='ME'),'01010691-a677-5393-2527-22f00ac0a2ec','https://example.com/events/e19',((date_trunc('day',now() AT TIME ZONE 'Europe/Podgorica')+interval '6 days'+time '20:00') AT TIME ZONE 'Europe/Podgorica'),((date_trunc('day',now() AT TIME ZONE 'Europe/Podgorica')+interval '6 days'+time '20:00') AT TIME ZONE 'Europe/Podgorica')+interval '2 hours','Europe/Podgorica',true),
  ('e30ee732-5cf9-56d0-bb3a-cc58665ace6d','Fortress Maps Exhibition','Historic and modern maps of the Herceg Novi fortresses, with notes on how each map was made. The exhibition runs all day on the terrace.','1912d8a0-ca7a-4d6f-d457-7b1536472244',(SELECT id FROM country WHERE iso_code='ME'),'aa89ce08-7933-741a-3b89-fadc0bddf6fc','https://example.com/events/e20',((date_trunc('day',now() AT TIME ZONE 'Europe/Podgorica')+interval '8 days'+time '12:00') AT TIME ZONE 'Europe/Podgorica'),((date_trunc('day',now() AT TIME ZONE 'Europe/Podgorica')+interval '8 days'+time '12:00') AT TIME ZONE 'Europe/Podgorica')+interval '2 hours','Europe/Podgorica',true),
  ('3f13eedd-84c9-b32b-4ff0-6eef0bc6ef69','Kotor Under Glass: Architecture Talks','Three short talks on how the town architecture has survived earthquakes and tourism. Speakers compare old and new restoration methods.','265494df-c98d-acbb-dc05-426a45d520f7',(SELECT id FROM country WHERE iso_code='ME'),'4b5ebf56-603d-7596-1708-f9c09b9cc90b','https://example.com/events/e21',((date_trunc('day',now() AT TIME ZONE 'Europe/Podgorica')+interval '9 days'+time '18:00') AT TIME ZONE 'Europe/Podgorica'),((date_trunc('day',now() AT TIME ZONE 'Europe/Podgorica')+interval '9 days'+time '18:00') AT TIME ZONE 'Europe/Podgorica')+interval '2 hours','Europe/Podgorica',false),
  ('afcf6f3c-cdc8-dce0-ecc0-379d1ba13e56','Robotics for Teens','A hands-on robotics workshop for teenagers, building a line-following robot in teams. Parents are welcome to watch the final demo.','6abd4bc9-463d-2bfe-42d3-c55d6d3f9e77',(SELECT id FROM country WHERE iso_code='ME'),'767d1422-9706-bae1-18b5-5e83fd222f0c','https://example.com/events/e22',((date_trunc('day',now() AT TIME ZONE 'Europe/Podgorica')+interval '10 days'+time '14:00') AT TIME ZONE 'Europe/Podgorica'),((date_trunc('day',now() AT TIME ZONE 'Europe/Podgorica')+interval '10 days'+time '14:00') AT TIME ZONE 'Europe/Podgorica')+interval '2 hours','Europe/Podgorica',false),
  ('775be5ed-de4a-70d4-7b7b-60e1450f253f','Stand-Up Paddle and Ocean Science','A paddle session with a marine biologist who explains the sea life and currents you pass. Beginners are welcome with a certified instructor.','c57bab45-6cb6-01fa-d479-a04f4685bcee',(SELECT id FROM country WHERE iso_code='ME'),'443eacec-60fb-5b82-ee78-f40218d05227','https://example.com/events/e23',((date_trunc('day',now() AT TIME ZONE 'Europe/Podgorica')+interval '12 days'+time '09:00') AT TIME ZONE 'Europe/Podgorica'),((date_trunc('day',now() AT TIME ZONE 'Europe/Podgorica')+interval '12 days'+time '09:00') AT TIME ZONE 'Europe/Podgorica')+interval '2 hours','Europe/Podgorica',false),
